import LiquidRevealCursor from '@/components/mfa/LiquidRevealCursor'

// Once, e.g. in your root layout. It follows the pointer over the whole page,
// never blocks clicks, and turns itself off on touch screens.
export default function Layout({children}: {children: React.ReactNode}) {
  return (
    <>
      {children}
      <LiquidRevealCursor />
      {/* or reveal your own layer:
      <LiquidRevealCursor><div className="h-full bg-linear-to-br from-orange-400 to-violet-600" /></LiquidRevealCursor> */}
    </>
  )
}
